import{_ as l,o as e,c as i,a2 as r}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"《風平浪靜 NagiAsu.xyz》使用者服務條款","description":"本伺服的使用者服務條款，請玩家們遵守。","frontmatter":{"title":"《風平浪靜 NagiAsu.xyz》使用者服務條款","description":"本伺服的使用者服務條款，請玩家們遵守。"},"headers":[],"relativePath":"rule/index.md","filePath":"rule.md"}'),t={name:"rule/index.md"};function o(n,a,u,s,h,d){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="使用者服務條款" tabindex="-1">使用者服務條款 <a class="header-anchor" href="#使用者服務條款" aria-label="Permalink to &quot;使用者服務條款&quot;">​</a></h1><p>《風平浪靜 NagiAsu.xyz》，提供Minecraft多人伺服器遊玩、Discord社群、網站、資訊、服務等，供使用者遊玩與使用。</p><p>本服務條款為伺服方和遊玩方共同遵守之契約，當您使用本伺服所提供之服務時，即視為您<strong>已完全了解並同意本服務條款</strong>；若您對本服務條款有任何疑慮，應立即向伺服方詢問。</p><p>若您不同意本服務條款，遊玩方不得使用任何本伺服所提供之相關服務。</p><h3 id="公共頻道發言-請遵守公共頻道聊天規範" tabindex="-1">公共頻道發言，請遵守<a href="/rule/chat/"><b>公共頻道聊天規範</b></a> <a class="header-anchor" href="#公共頻道發言-請遵守公共頻道聊天規範" aria-label="Permalink to &quot;公共頻道發言，請遵守[&lt;b&gt;公共頻道聊天規範&lt;/b&gt;](./rule/chat.md)&quot;">​</a></h3><ul><li>同時亦須遵守 <a href="https://discord.com/guidelines" target="_blank" rel="noreferrer">Discord社群守則</a></li><li>此為獨立頁面超連結，請點擊上方連結查看</li></ul><h3 id="請勿影響其他玩家遊玩" tabindex="-1">請勿影響其他玩家遊玩 <a class="header-anchor" href="#請勿影響其他玩家遊玩" aria-label="Permalink to &quot;請勿影響其他玩家遊玩&quot;">​</a></h3><ul><li><strong>影響他人</strong>的行為係指： <ul><li>破壞、偷竊、騷擾、詐欺、誤導、盜畫、影響效能...</li></ul></li><li>基本上，在路上看到人造建築與箱子不要任意去亂碰</li></ul><h3 id="嚴禁使用外掛功能-遊戲bug" tabindex="-1">嚴禁使用外掛功能/遊戲BUG <a class="header-anchor" href="#嚴禁使用外掛功能-遊戲bug" aria-label="Permalink to &quot;嚴禁使用外掛功能/遊戲BUG&quot;">​</a></h3><ul><li><a href="/rule/modrule/">容許與禁止的詳細說明</a></li></ul><h3 id="請勿開分身或使用vpn遊玩" tabindex="-1">請勿開分身或使用VPN遊玩 <a class="header-anchor" href="#請勿開分身或使用vpn遊玩" aria-label="Permalink to &quot;請勿開分身或使用VPN遊玩&quot;">​</a></h3><ul><li>若有這類需求，請務必<b>主動</b>利用<a href="/contact/">客服</a>向伺服人員詢問或提出申請</li><li>違反本項規定將依照伺服人員之認定進行處置</li></ul><h3 id="嚴禁影響伺服營運" tabindex="-1">嚴禁影響伺服營運 <a class="header-anchor" href="#嚴禁影響伺服營運" aria-label="Permalink to &quot;嚴禁影響伺服營運&quot;">​</a></h3><ul><li>進行相關攻擊行為</li><li>對伺服造成任何負面或名譽損害</li><li>濫用本伺服所提供之服務，或侵害本伺服智慧財產權</li><li>其他經伺服方認定可能造成營運受影響之行為</li></ul><h2 id="備註" tabindex="-1">備註 <a class="header-anchor" href="#備註" aria-label="Permalink to &quot;備註&quot;">​</a></h2><ul><li>伺服處理以電磁紀錄(包括但不限於帳號/IP/遊玩行為)為準，請務必保管好個人帳號 <ul><li>切勿將您的帳號外借給任何人，若發生任何狀況須自行承擔全責</li><li>帳號之所有行為皆視為您本人之行為，不接受任何因個人因素導致之理由(朋友玩的/家人玩的/帳號被盜...)作為要求重新提供服務之依據。</li></ul></li><li>若發現有玩家有違反以上規定時，請即時利用<a href="/discord/customer_service/">客服系統</a>通報，切勿知情不報</li><li>除現有上述規範外，若因特殊情況致使伺服方無法繼續以本遊玩契約來提供遊玩服務，伺服方保有隨時向該玩家終止遊玩契約之權利</li><li>使用者可隨時以任何形式向伺服方告知終止遊玩契約</li></ul><p><font size="4"><a href="/rule/punish/">終止遊玩條款與上訴</a></font></p><p>最後更新時間 : 2023/02/23</p>',18)])])}const f=l(t,[["render",o]]);export{p as __pageData,f as default};
